#!/usr/bin/env python3
"""Filter and aggregate RFC-style CSV files."""

from __future__ import annotations

import argparse
import csv
from decimal import Decimal, InvalidOperation, localcontext
import json
import math
from pathlib import Path
import sys
from typing import Iterable, Sequence


class UserError(Exception):
    """An input or command-line error suitable for displaying to the user."""


def parse_args(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows and optionally calculate grouped sums/averages."
    )
    parser.add_argument("input", metavar="INPUT.csv", type=Path)
    parser.add_argument(
        "--where", action="append", default=[], metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN")
    parser.add_argument(
        "--sum", dest="sum_columns", action="append", default=[], metavar="COLUMN"
    )
    parser.add_argument(
        "--avg", dest="avg_columns", action="append", default=[], metavar="COLUMN"
    )
    parser.add_argument("--output", choices=("json", "csv"), default="json")
    args = parser.parse_args(argv)

    if (args.sum_columns or args.avg_columns) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    if args.group_by and not (args.sum_columns or args.avg_columns):
        parser.error("--group-by requires --sum or --avg")
    return args


def parse_filters(values: Iterable[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for value in values:
        if "=" not in value:
            raise UserError(
                f"malformed filter {value!r}: expected COLUMN=VALUE"
            )
        column, expected = value.split("=", 1)
        if not column:
            raise UserError(
                f"malformed filter {value!r}: column name must not be empty"
            )
        filters.append((column, expected))
    return filters


def validate_headers(headers: list[str]) -> None:
    if not headers:
        raise UserError("input has no header row")
    empty_positions = [str(i + 1) for i, name in enumerate(headers) if not name]
    if empty_positions:
        raise UserError(
            "header names must not be empty (field " + ", ".join(empty_positions) + ")"
        )
    seen: set[str] = set()
    duplicates: list[str] = []
    for name in headers:
        if name in seen and name not in duplicates:
            duplicates.append(name)
        seen.add(name)
    if duplicates:
        raise UserError("duplicate header name(s): " + ", ".join(repr(x) for x in duplicates))


def require_columns(headers: list[str], requested: Iterable[str]) -> None:
    known = set(headers)
    for column in requested:
        if column not in known:
            raise UserError(f"unknown column: {column!r}")


def read_rows(path: Path) -> tuple[list[str], list[tuple[int, dict[str, str]]]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as stream:
            reader = csv.reader(stream, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise UserError("input is empty") from None
            validate_headers(headers)

            rows: list[tuple[int, dict[str, str]]] = []
            for record_number, fields in enumerate(reader, start=2):
                if len(fields) != len(headers):
                    raise UserError(
                        f"row {record_number} has {len(fields)} fields; "
                        f"expected {len(headers)}"
                    )
                rows.append((record_number, dict(zip(headers, fields))))
            return headers, rows
    except UserError:
        raise
    except csv.Error as exc:
        line = getattr(locals().get("reader"), "line_num", None)
        location = f" near line {line}" if line else ""
        raise UserError(f"malformed CSV{location}: {exc}") from exc
    except UnicodeError as exc:
        raise UserError(f"input is not valid UTF-8: {exc}") from exc
    except OSError as exc:
        raise UserError(f"cannot read {path}: {exc}") from exc


def parse_number(value: str, row_number: int, column: str) -> Decimal:
    if value == "":
        raise UserError(f"row {row_number}, column {column!r}: blank numeric value")
    try:
        number = Decimal(value)
    except InvalidOperation as exc:
        raise UserError(
            f"row {row_number}, column {column!r}: invalid numeric value {value!r}"
        ) from exc
    if not number.is_finite():
        raise UserError(
            f"row {row_number}, column {column!r}: invalid numeric value {value!r}"
        )
    return number


def decimal_precision(values: list[Decimal]) -> int:
    """Return enough context precision to add the finite decimals exactly."""
    if not values:
        return 28
    nonzero = [value for value in values if value]
    if not nonzero:
        return 28
    highest_place = max(value.adjusted() for value in nonzero)
    lowest_place = min(value.as_tuple().exponent for value in values)
    carry_digits = math.ceil(math.log10(len(values) + 1))
    return max(28, highest_place - lowest_place + carry_digits + 2)


def minimal_decimal(value: Decimal) -> str:
    if not value:
        return "0"
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def aggregate(
    rows: list[tuple[int, dict[str, str]]],
    group_column: str,
    sum_columns: list[str],
    avg_columns: list[str],
) -> tuple[list[str], list[dict[str, str]]]:
    numeric_columns = list(dict.fromkeys(sum_columns + avg_columns))
    groups: dict[str, dict[str, list[Decimal]]] = {}
    for row_number, row in rows:
        parsed = {
            column: parse_number(row[column], row_number, column)
            for column in numeric_columns
        }
        group = groups.setdefault(
            row[group_column], {column: [] for column in numeric_columns}
        )
        for column, number in parsed.items():
            group[column].append(number)

    output_headers = (
        [group_column]
        + [f"sum_{column}" for column in sum_columns]
        + [f"avg_{column}" for column in avg_columns]
    )
    output_rows: list[dict[str, str]] = []
    for group_value in sorted(groups):
        values_by_column = groups[group_value]
        totals: dict[str, Decimal] = {}
        for column, values in values_by_column.items():
            with localcontext() as context:
                context.prec = decimal_precision(values)
                totals[column] = sum(values, Decimal(0))

        output: dict[str, str] = {group_column: group_value}
        for column in sum_columns:
            output[f"sum_{column}"] = minimal_decimal(totals[column])
        for column in avg_columns:
            values = values_by_column[column]
            with localcontext() as context:
                context.prec = max(28, decimal_precision(values))
                average = totals[column] / Decimal(len(values))
            output[f"avg_{column}"] = minimal_decimal(average)
        output_rows.append(output)
    return output_headers, output_rows


def emit_json(rows: list[dict[str, str]]) -> None:
    json.dump(rows, sys.stdout, ensure_ascii=False, indent=2)
    sys.stdout.write("\n")


def emit_csv(headers: list[str], rows: list[dict[str, str]]) -> None:
    writer = csv.DictWriter(
        sys.stdout, fieldnames=headers, extrasaction="raise", lineterminator="\r\n"
    )
    writer.writeheader()
    writer.writerows(rows)


def run(argv: Sequence[str] | None = None) -> int:
    args = parse_args(argv)
    filters = parse_filters(args.where)
    headers, numbered_rows = read_rows(args.input)
    require_columns(
        headers,
        [column for column, _ in filters]
        + ([args.group_by] if args.group_by else [])
        + args.sum_columns
        + args.avg_columns,
    )

    filtered = [
        (number, row)
        for number, row in numbered_rows
        if all(row[column] == expected for column, expected in filters)
    ]

    if args.group_by:
        output_headers, output_rows = aggregate(
            filtered, args.group_by, args.sum_columns, args.avg_columns
        )
    else:
        output_headers = headers
        output_rows = [row for _, row in filtered]

    if args.output == "json":
        emit_json(output_rows)
    else:
        emit_csv(output_headers, output_rows)
    return 0


def main() -> int:
    try:
        return run()
    except UserError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
import csv
import io
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest


PROJECT = Path(__file__).resolve().parent
PROGRAM = PROJECT / "main.py"


class CsvInsightsTests(unittest.TestCase):
    def invoke(self, content: str, *arguments: str) -> subprocess.CompletedProcess[str]:
        with tempfile.TemporaryDirectory() as directory:
            source = Path(directory) / "input.csv"
            source.write_text(content, encoding="utf-8", newline="")
            before = source.read_bytes()
            result = subprocess.run(
                [sys.executable, str(PROGRAM), str(source), *arguments],
                text=True,
                capture_output=True,
                check=False,
            )
            self.assertEqual(source.read_bytes(), before, "input file was modified")
            return result

    def test_filter_preserves_quoted_fields_embedded_newline_and_order(self):
        content = 'name,team,note\r\nAlice,A,"hello, world"\r\nBob,B,"two\r\nlines"\r\nCara,A,last\r\n'
        result = self.invoke(content, "--where", "team=A")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            json.loads(result.stdout),
            [
                {"name": "Alice", "team": "A", "note": "hello, world"},
                {"name": "Cara", "team": "A", "note": "last"},
            ],
        )

    def test_multiple_filters_are_and_and_value_may_contain_equals(self):
        content = "a,b\n1,x=y\n1,no\n2,x=y\n"
        result = self.invoke(content, "--where", "a=1", "--where", "b=x=y")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(json.loads(result.stdout), [{"a": "1", "b": "x=y"}])

    def test_grouped_sum_and_average_are_sorted_minimal_decimal_strings(self):
        content = "team,amount,units\nB,0.10,1\nA,1.20,2\nB,0.20,2\nA,1.30,5\n"
        result = self.invoke(
            content, "--group-by", "team", "--sum", "amount", "--avg", "units"
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            json.loads(result.stdout),
            [
                {"team": "A", "sum_amount": "2.5", "avg_units": "3.5"},
                {"team": "B", "sum_amount": "0.3", "avg_units": "1.5"},
            ],
        )

    def test_csv_output_has_header_and_round_trips(self):
        result = self.invoke('name,note\nA,"x,y"\n', "--output", "csv")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(
            list(csv.reader(io.StringIO(result.stdout, newline=""))),
            [["name", "note"], ["A", "x,y"]],
        )

    def test_rejects_bad_headers_and_wrong_field_count(self):
        for content, expected in (
            ("a,a\n1,2\n", "duplicate header"),
            ("a,\n1,2\n", "must not be empty"),
            ("a,b\n1\n", "row 2 has 1 fields"),
        ):
            with self.subTest(content=content):
                result = self.invoke(content)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn(expected, result.stderr)

    def test_rejects_unknown_columns_filters_and_invalid_numbers(self):
        cases = [
            (("--where", "missing=x"), "unknown column"),
            (("--where", "broken"), "malformed filter"),
            (("--group-by", "team", "--sum", "amount"), "row 2, column 'amount'"),
        ]
        for arguments, expected in cases:
            with self.subTest(arguments=arguments):
                result = self.invoke("team,amount\nA,nope\n", *arguments)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn(expected, result.stderr)

    def test_invalid_number_in_filtered_out_row_is_ignored(self):
        result = self.invoke(
            "team,amount\nA,2\nB,nope\n",
            "--where", "team=A", "--group-by", "team", "--avg", "amount",
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(json.loads(result.stdout), [{"team": "A", "avg_amount": "2"}])


if __name__ == "__main__":
    unittest.main()
# CSV Insights

A dependency-free Python 3.11+ command-line tool for filtering CSV files and
calculating grouped sums and averages with decimal arithmetic.

```text
python3 main.py INPUT.csv [--where COLUMN=VALUE ...] [--group-by COLUMN]
                          [--sum COLUMN] [--avg COLUMN] [--output json|csv]
```

Filters are exact string comparisons and repeated filters combine with AND.
Without aggregation, matching rows are emitted in their original order. `--sum`
and `--avg` may each be repeated, and require `--group-by`. Output defaults to
JSON; select RFC-compatible CSV with `--output csv`.

Examples:

```sh
python3 main.py sales.csv --where region=North
python3 main.py sales.csv --group-by region --sum revenue --avg units --output csv
```

Input must be UTF-8 CSV with a non-empty, unique header and a consistent field
count. Invalid or blank numeric cells in selected rows are reported with their
row and column. The input file is only read and is never modified.

Run the self-tests with:

```sh
python3 -m unittest -v
```
